INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('be9d5286-0a3e-4dbf-aa8d-f41237d8df95', 'b2b2b2b2-3030-4000-8000-000000000002', 21, 'Dia 21 — Esperança', 'Semana 3: Reconstruir', '{"pch": "O Deus da esperan\u00e7a vos encha de alegria e paz\u2026 A esperan\u00e7a \u00e9 uma pessoa, n\u00e3o um sentimento.", "verse": "Rm 15,13", "lectio": "Leia Rm 15,13. Transbordar de esperan\u00e7a.", "practice": "Escreva 3 coisas que ainda espera ver acontecer.", "question": "Em que voc\u00ea ainda espera?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;